export const BODY: string = "\n<p>PNG فائلیں بہت بڑی ہوتی ہیں، اور JPG میں بدلنے سے وہ اکثر دس گنا چھوٹی ہو جاتی ہیں۔ یہ بچت ای میل، ویب سائٹ اور فون کی جگہ کے لیے بہت اہم ہے۔</p>\n<p>لیکن تبدیلی میں معیار کا سوال بھی ہے: کتنا معیار رکھیں کہ تصویر تیز رہے اور فائل بھی چھوٹی ہو۔ غلط سیٹنگ سے متن دھندلا ہو جاتا ہے یا فائل پھر بھی بڑی رہتی ہے۔</p>\n<p>یہ مضمون بتاتا ہے کہ PNG بڑا کیوں ہے، ہر تصویر کی قسم میں کتنی بچت ہوتی ہے، اور ہر معیار پر متن و فوٹو کیسے نظر آتے ہیں۔ تبدیل کرنے کے لیے <a href=\"/ur/png-ko-jpg-mein-convert-karein/\">PNG ٹو JPG</a> استعمال کریں۔</p>\n<h2 id=\"why-png-is-big\">PNG فائلیں اتنی بڑی کیوں ہیں</h2>\n<p>PNG بغیر نقصان کے کمپریس کرتا ہے، اس لیے وہ ہر پکسل کی مکمل معلومات بچاتا ہے۔ فوٹو میں ہر پکسل الگ رنگ رکھتا ہے، جس سے فائل بہت بڑی ہو جاتی ہے۔</p>\n<p>PNG گرافکس کے لیے بنایا گیا تھا، جہاں چند رنگ ہوتے ہیں اور فائل چھوٹی رہتی ہے۔ فوٹو میں ہزاروں رنگ ہوتے ہیں، اس لیے PNG وہاں ناکام ہوتا ہے۔</p>\n<p>PNG کی بڑی فائل کا مطلب ہے سست اپ لوڈ اور زیادہ جگہ۔ فوٹو کو PNG میں رکھنا جگہ ضائع کرنا ہے۔</p>\n<h2 id=\"why-jpg-is-small\">JPG فائلیں اتنی چھوٹی کیوں ہیں</h2>\n<p>JPG نقصان دہ کمپریشن کرتا ہے: وہ آنکھ کو مشکل سے نظر آنے والی تفصیل پھینک دیتا ہے۔ اس سے فائل بہت چھوٹی ہو جاتی ہے، بغیر تصویر خراب کیے۔</p>\n<p>JPG کا معیار سلائیڈر سے قابو ہوتا ہے: 80 پر فائل چھوٹی اور تصویر تیز، 95 پر فائل بڑی اور تصویر بہترین۔ ہر کام کے لیے الگ معیار درست ہے۔</p>\n<p>JPG کی چھوٹی فائل کا مطلب ہے تیز ویب سائٹ اور آسان ای میل۔ یہی وجہ ہے کہ فوٹو کے لیے JPG عالمی معیار ہے۔</p>\n<h2 id=\"savings-by-image-type\">ہر تصویر کی قسم میں بچت</h2>\n<p>فوٹو میں بچت سب سے زیادہ ہے: 5MB PNG فوٹو JPG میں 500KB بن سکتی ہے، یعنی دس گنا بچت۔ اسکرین شاٹ میں بچت کم ہے، کیونکہ متن JPG میں خراب ہوتا ہے۔</p>\n<p>سادہ گرافکس میں بچت درمیانی ہے: چند رنگوں والا لوگو PNG میں بھی چھوٹا رہتا ہے۔ لیکن فوٹو جیسی تفصیل والی تصویر میں JPG ہمیشہ جیتتا ہے۔</p>\n<p>بچت جانچنے کے لیے ایک تصویر تبدیل کریں اور دونوں فائلوں کا سائز دیکھیں۔ اگر بچت پانچ گنا سے زیادہ ہو تو تبدیلی ضرور کریں۔</p>\n<h2 id=\"quality-slider-maths\">معیار کا سلائیڈر، عملی حساب سے</h2>\n<p>معیار 90 پر فائل بڑی اور تصویر بہترین ہوتی ہے۔ معیار 80 پر فائل آدھی ہو جاتی ہے اور فرق مشکل سے نظر آتا ہے۔ معیار 70 پر فائل اور چھوٹی ہوتی ہے، مگر متن دھندلا ہونے لگتا ہے۔</p>\n<p>حساب یہ ہے: ہر دس پوائنٹ کم کرنے پر فائل تقریباً آدھی ہو جاتی ہے۔ 90 سے 80 جانے پر فائل آدھی، اور 80 سے 70 جانے پر پھر آدھی ہو جاتی ہے۔</p>\n<p>بہترین توازن 80 سے 85 ہے، جہاں فائل چھوٹی اور تصویر تیز رہتی ہے۔ اس سے نیچے جانا صرف اس وقت درست ہے جب فائل سائز سب سے اہم ہو۔</p>\n<h2 id=\"text-at-each-quality\">ہر معیار پر متن کی وضاحت</h2>\n<p>معیار 90 پر متن بالکل تیز رہتا ہے، جیسے اصل PNG میں۔ معیار 80 پر متن تھوڑا نرم ہوتا ہے، مگر پڑھنے کے قابل رہتا ہے۔</p>\n<p>معیار 70 پر متن کے گرد ہالہ نظر آنے لگتا ہے اور چھوٹا متن پڑھنا مشکل ہو جاتا ہے۔ معیار 60 سے نیچے متن ناقابل خواندگی ہو جاتا ہے۔</p>\n<p>متن والی تصویر کے لیے معیار 85 سے کم نہ رکھیں۔ اگر فائل بڑی ہو تو ابعاد کم کریں، معیار کم نہ کریں۔</p>\n<h2 id=\"photos-at-each-quality\">ہر معیار پر فوٹو کا معیار</h2>\n<p>فوٹو معیار 80 پر بھی اچھی لگتی ہے، کیونکہ اس میں نرم رنگ ہوتے ہیں۔ معیار 70 پر بھی فوٹو قابل قبول رہتی ہے، خاص طور پر چھوٹی اسکرین پر۔</p>\n<p>فوٹو میں نقصان سب سے پہلے آسمان اور جلد میں نظر آتا ہے۔ اگر وہ صاف لگیں تو معیار کافی ہے، ورنہ معیار بڑھائیں۔</p>\n<p>پرنٹ کے لیے فوٹو کا معیار 90 سے اوپر رکھیں، کیونکہ کاغذ پر ہلکا نقصان بھی نظر آتا ہے۔ ویب کے لیے 80 کافی ہے۔</p>\n<h2 id=\"when-savings-disappear\">بچت کب ختم ہو جاتی ہے</h2>\n<p>بچت اس وقت ختم ہوتی ہے جب PNG تصویر پہلے ہی چھوٹی ہو، جیسے سادہ آئیکن۔ ایسی تصویر کو JPG میں بدلنے سے فائل بڑی بھی ہو سکتی ہے۔</p>\n<p>بچت اس وقت بھی کم ہوتی ہے جب معیار بہت زیادہ رکھا جائے۔ 95 معیار پر JPG فائل PNG کے قریب ہو جاتی ہے، بغیر کوئی فائدہ دیے۔</p>\n<p>تبدیلی سے پہلے فائل کا سائز جانچیں۔ اگر JPG بڑا نکلے تو PNG ہی رکھیں۔</p>\n<h2 id=\"choosing-the-right-setting\">اپنے کام کے لیے درست سیٹنگ چننا</h2>\n<p>ویب فوٹو کے لیے 80، اسکرین شاٹ کے لیے 85، اور پرنٹ کے لیے 90 چنیں۔ ہر کام کی اپنی سیٹنگ ہے، ایک سیٹنگ سب کے لیے نہیں۔</p>\n<p>سیٹنگ چننے کے بعد نتیجہ کو مکمل سائز میں دیکھیں۔ اگر تصویر صاف لگے تو سیٹنگ درست ہے، ورنہ معیار بڑھائیں۔</p>\n<p>ایک ہی کام کے لیے ایک ہی سیٹنگ رکھیں، تاکہ سب تصویریں یکساں لگیں۔ مستقل سیٹنگ کام تیز کرتی ہے۔</p>\n<h2 id=\"comparing-before-after\">پہلے اور بعد کا درست موازنہ</h2>\n<p>موازنہ کرتے وقت دونوں تصویروں کو ایک ہی سائز میں دیکھیں۔ چھوٹے پیش منظر پر فرق چھپ جاتا ہے، اس لیے مکمل سائز میں دیکھیں۔</p>\n<p>موازنہ میں تین جگہیں دیکھیں: آسمان، جلد اور متن کے کنارے۔ یہ تین جگہیں سب سے پہلے فرق دکھاتی ہیں۔</p>\n<p>اگر موازنہ میں فرق نظر نہ آئے تو چھوٹی فائل چنیں۔ فرق نہ ہونا ہی کامیاب تبدیلی کی نشانی ہے۔</p>\n<h2 id=\"batch-savings\">بیچ بچت تیزی سے جمع ہوتی ہے</h2>\n<p>ایک تصویر میں 5MB بچت چھوٹی لگتی ہے، مگر سو تصویروں میں 500MB بن جاتی ہے۔ پوری کیٹلاگ یا البم کی بیچ تبدیلی سے فون اور کلاؤڈ کی جگہ بہت بچتی ہے۔</p>\n<p>بیچ میں سب تصویروں پر ایک ہی معیار لگائیں، تاکہ نتیجہ یکساں ہو۔ بیچ کا نتیجہ ZIP میں ملتا ہے۔</p>\n<p>بیچ بدلنے سے پہلے ایک تصویر آزمائیں۔ اگر وہ اچھی لگے تو پوری بیچ بدلیں، ورنہ سیٹنگ بدلیں۔</p>\n<h2 id=\"when-not-to-convert\">کب بالکل تبدیل نہ کریں</h2>\n<p>جب تصویر میں شفافیت ہو تو تبدیل نہ کریں، کیونکہ JPG شفافیت مٹا دیتا ہے۔ لوگو اور آئیکن کو PNG میں ہی رکھیں۔</p>\n<p>جب تصویر کو بار بار ایڈٹ کرنا ہو تو بھی تبدیل نہ کریں۔ PNG ماسٹر کے طور پر رکھیں اور آخر میں JPG بنائیں۔</p>\n<p>جب PNG فائل پہلے ہی چھوٹی ہو تو بھی تبدیل نہ کریں۔ بچت نہ ہونے پر تبدیلی کا کوئی فائدہ نہیں۔</p>\n<h2 id=\"webp-alternative\">WebP متبادل جو جاننے کے قابل ہے</h2>\n<p>WebP JPG سے بھی چھوٹا ہوتا ہے، اسی معیار پر۔ اگر آپ کو سب سے چھوٹی فائل چاہیے تو PNG کو WebP میں بدلیں، JPG میں نہیں۔</p>\n<p>WebP شفافیت بھی بچاتا ہے، اس لیے وہ PNG کا بہتر متبادل ہے۔ لیکن WebP ہر جگہ نہیں کھلتا، اس لیے مطابقت جانچیں۔</p>\n<p>ویب کے لیے WebP، شیئرنگ کے لیے JPG چنیں۔ دونوں PNG سے بہتر ہیں۔</p>\n<h2 id=\"email-attachment-limits\">ای میل اٹیچمنٹ کی حدیں</h2>\n<p>زیادہ تر ای میل 25MB تک کی فائل لیتی ہے۔ PNG تصویریں اس حد کو جلدی بھر دیتی ہیں، جبکہ JPG میں درجنوں تصویریں اسی حد میں آ جاتی ہیں۔</p>\n<p>ای میل کے لیے تصویروں کو JPG میں بدلیں اور معیار 80 رکھیں۔ اس سے فائل ہلکی رہتی ہے اور وصول کرنے والا جلدی ڈاؤن لوڈ کرتا ہے۔</p>\n<p>اگر ای میل میں بہت سی تصویریں ہوں تو انہیں ZIP میں ڈال کر بھیجیں۔ ZIP فائل چھوٹی اور منظم رہتی ہے۔</p>\n<h2 id=\"website-loading-speed\">ویب سائٹ لوڈ ہونے کی رفتار</h2>\n<p>PNG تصویریں ویب سائٹ کو سست کر دیتی ہیں، کیونکہ وہ بہت بڑی ہوتی ہیں۔ JPG میں بدلنے سے صفحہ تیزی سے کھلتا ہے اور وزیٹر خوش رہتا ہے۔</p>\n<p>ہر 100KB بچت صفحے کو تیز کرتی ہے۔ سو تصویروں والی سائٹ پر یہ بچت سیکنڈوں کا فرق بناتی ہے۔</p>\n<p>ویب سائٹ کی ہر PNG فوٹو کو JPG یا WebP میں بدلیں۔ صرف لوگو PNG میں رکھیں۔</p>\n<h2 id=\"storage-on-phone\">بھرے ہوئے فون پر جگہ</h2>\n<p>فون میں PNG اسکرین شاٹ بہت جگہ لیتے ہیں۔ انہیں JPG میں بدلنے سے گیلری کی جگہ بہت بچتی ہے۔</p>\n<p>فون کی جگہ بچانے کے لیے پرانی PNG تصویریں بیچ میں بدلیں۔ اصل PNG کو کلاؤڈ میں رکھیں اور فون میں JPG نقل رکھیں۔</p>\n<p>فون میں جگہ بچانے کا بہترین طریقہ یہ ہے کہ نئی تصویریں JPG میں لیں۔ کیمرے کی سیٹنگ میں JPG چنیں۔</p>\n<h2 id=\"upload-limits-forms\">فارم پر اپ لوڈ کی حدیں</h2>\n<p>فارم اکثر 2MB یا 5MB کی حد لگاتے ہیں۔ PNG تصویر اس حد سے باہر ہو سکتی ہے، جبکہ JPG میں وہی تصویر آرام سے اندر آ جاتی ہے۔</p>\n<p>فارم کے لیے تصویر کو JPG میں بدلیں اور معیار 80 رکھیں۔ اپ لوڈ سے پہلے فائل کا سائز جانچیں، تاکہ مسترد نہ ہو۔</p>\n<p>اگر فارم پھر بھی مسترد کرے تو ابعاد کم کریں۔ ابعاد کم کرنے سے فائل اور چھوٹی ہو جاتی ہے۔</p>\n<h2 id=\"balancing-quality-batch\">بیچ بھر معیار کا توازن</h2>\n<p>بیچ میں سب تصویروں پر ایک ہی معیار نہ لگائیں: فوٹو کے لیے 80 اور اسکرین شاٹ کے لیے 85 رکھیں۔ ہر قسم کی اپنی سیٹنگ ہے۔</p>\n<p>بیچ بدلنے کے بعد چند تصویریں کھول کر جانچیں۔ اگر کوئی تصویر دھندلی لگے تو اسے الگ سے زیادہ معیار پر بدلیں۔</p>\n<p>توازن کا مطلب ہے کہ سب تصویریں صاف لگیں اور فائل بھی ہلکی رہے۔ ایک سیٹنگ سب کے لیے درست نہیں۔ مکمل رہنما <a href=\"/ur/blog/png-ko-jpg-rehnumai/\">PNG ٹو JPG رہنما</a> میں اور عملی مراحل <a href=\"/ur/blog/png-ko-jpg-mein-kaise-convert-karein/\">PNG کو JPG میں کیسے بدلیں</a> میں دیکھیں۔ WebP چاہیے ہو تو <a href=\"/ur/png-ko-webp-mein-convert-karein/\">PNG ٹو WebP</a> استعمال کریں۔</p>\n";

